-- =============================================================================
-- menu_iconos_color_20261114.sql — Íconos en colores de las opciones nuevas de Fiscalización
-- =============================================================================
--
-- Las opciones que se agregaron después de sql/menu_iconos_color_20261111.sql y
-- quedaron sin ícono, con el mismo juego (Fluent UI System Color Icons, MIT,
-- 18 × 18; de @iconify-json/fluent-color 1.2.21). Los degradados llevan un id
-- propio (m<id de menú>…) y el filtro svg_unico de app.py los vuelve a renombrar
-- al dibujarlos. Por URL: no depende del id que le tocó a cada opción.
--
-- Correrlo ENTERO (Alt+X). Idempotente. El menú se lee en cada pantalla: alcanza
-- con recargar.

USE sindicato;
SET NAMES utf8mb4;

